insert into quiz_videos (cible,questions,statut,source) values ('zone:7f804f43-4f01-4785-81d8-af8887b38995','[{"question": "Comment appelle-t-on la façon de se laver avant la prière ?", "choix": ["Les ablutions (le woudou)", "Le petit-déjeuner", "La récréation"], "bonne": 0, "explication": "Avant de prier, on fait les ablutions (en arabe : al-woudou'').", "emoji": "💧", "arabe": "الوُضُوء"}, {"question": "Pourquoi fait-on les ablutions ?", "choix": ["Pour être propre et prêt à prier", "Pour jouer avec l''eau", "Pour se rafraîchir seulement"], "bonne": 0, "explication": "Les ablutions nous purifient avant de prier Allah.", "emoji": "🕌", "arabe": null}, {"question": "Avant quoi doit-on avoir ses ablutions ?", "choix": ["Avant la prière", "Avant de dormir seulement", "Avant de manger seulement"], "bonne": 0, "explication": "Sans ablutions, la prière n''est pas valable.", "emoji": "🤲", "arabe": null}, {"question": "Avec quoi fait-on les ablutions ?", "choix": ["Avec de l''eau propre", "Avec du savon seulement", "Avec du lait"], "bonne": 0, "explication": "On fait les ablutions avec de l''eau propre.", "emoji": "🚰", "arabe": null}]'::jsonb,'brouillon','sujet');
