insert into quiz_videos (cible,questions,statut,source) values ('zone:b28afebe-22d2-4366-a4bb-fd55bc76b2b8','[{"question": "Où se dit l''intention de faire les ablutions ?", "choix": ["Dans ta tête (ton cœur)", "À voix très haute", "On l''écrit sur un papier"], "bonne": 0, "explication": "L''intention, c''est te dire dans ta tête que tu te prépares.", "emoji": "🧠", "arabe": null}, {"question": "Pour quoi te prépares-tu quand tu fais les ablutions ?", "choix": ["Pour faire la prière ou lire le Coran", "Pour aller jouer au foot", "Pour regarder la télévision"], "bonne": 0, "explication": "Tu te prépares à faire la prière, ou à lire le Coran.", "emoji": "🕌", "arabe": null}, {"question": "Peut-on toucher le Coran sans avoir ses ablutions ?", "choix": ["Non, il faut avoir ses ablutions", "Oui, toujours", "Oui, seulement le soir"], "bonne": 0, "explication": "On ne touche pas le Coran sans ablutions ; sinon, on peut le prendre avec un gant propre.", "emoji": "📖", "arabe": null}, {"question": "Si tu n''as pas tes ablutions, avec quoi peux-tu toucher le Coran ?", "choix": ["Avec un gant propre", "Avec les mains sales", "Avec les pieds"], "bonne": 0, "explication": "La fiche le dit : avec un gant propre, tu peux le toucher.", "emoji": "🧤", "arabe": null}, {"question": "Quand tu as tes ablutions, que fait Allah pour toi ?", "choix": ["Il te protège encore plus du mal", "Il te donne des bonbons", "Rien du tout"], "bonne": 0, "explication": "Avec les ablutions, Allah te protège encore plus du mal.", "emoji": "🛡️", "arabe": null}]'::jsonb,'brouillon','sujet');
