insert into quiz_videos (cible,questions,statut,source) values ('zone:495721e0-2944-4744-9e26-fb73c469f5fe','[{"question": "Que veut dire « Bismillah » ?", "choix": ["Au nom d''Allah", "Merci beaucoup", "Au revoir"], "bonne": 0, "explication": "« Bismillah » veut dire « Au nom d''Allah ».", "emoji": "✨", "arabe": "بِسْمِ اللَّه"}, {"question": "Quand dis-tu « Bismillah » pendant les ablutions ?", "choix": ["Au début, avant de commencer à te laver", "À la fin seulement", "Jamais"], "bonne": 0, "explication": "On dit « Bismillah » au début des ablutions, juste après l''intention.", "emoji": "💧", "arabe": null}, {"question": "Si tu as oublié de dire « Bismillah », tes ablutions sont-elles encore bonnes ?", "choix": ["Oui, ce n''est pas grave, mais c''est mieux de le dire", "Non, il faut tout recommencer", "Non, tu ne peux plus prier de la journée"], "bonne": 0, "explication": "La fiche le dit : ce n''est pas grave si tu l''oublies, mais c''est mieux de le dire.", "emoji": "😊", "arabe": null}, {"question": "Qu''est-ce qui vient juste AVANT « Bismillah » dans les ablutions ?", "choix": ["L''intention", "Laver les pieds", "L''invocation de la fin"], "bonne": 0, "explication": "1 : avoir l''intention, 2 : dire « Bismillah ».", "emoji": "1️⃣", "arabe": null}]'::jsonb,'brouillon','sujet');
