insert into quiz_videos (cible,questions,statut,source) values ('zone:3252e744-7eac-4df2-af6b-90876c595b90','[{"question": "Combien de fois laves-tu tes mains ?", "choix": ["3 fois", "1 fois", "10 fois"], "bonne": 0, "explication": "On lave les 2 mains 3 fois.", "emoji": "✋", "arabe": null}, {"question": "Jusqu''où laves-tu tes mains ?", "choix": ["Jusqu''au poignet", "Jusqu''à l''épaule", "Seulement le bout des doigts"], "bonne": 0, "explication": "On frotte les mains jusqu''au poignet.", "emoji": "🖐️", "arabe": null}, {"question": "Que dois-tu frotter aussi, en plus du dessus et du dessous des mains ?", "choix": ["Entre les doigts", "Les cheveux", "Les genoux"], "bonne": 0, "explication": "On n''oublie pas de frotter entre les doigts.", "emoji": "🤲", "arabe": null}, {"question": "Avec quelle main prends-tu l''eau pour la mettre dans l''autre main ?", "choix": ["La main droite", "La main gauche", "Aucune"], "bonne": 0, "explication": "Tu prends l''eau avec la main droite et tu la mets dans la main gauche.", "emoji": "👉", "arabe": null}, {"question": "Pourquoi le faire 3 fois ?", "choix": ["Pour être sûr de l''avoir bien fait", "Parce que l''eau est froide", "Pour aller plus vite"], "bonne": 0, "explication": "1 ou 2 fois, ce n''est peut-être pas assez ; 3 fois, tu es sûr que c''est bien fait.", "emoji": "✅", "arabe": null}]'::jsonb,'brouillon','sujet');
