insert into quiz_videos (cible,questions,statut,source) values ('zone:9b4ac69d-ba8f-4996-8b12-00280c0fb213','[{"question": "Avec quelle main prends-tu l''eau pour la bouche ?", "choix": ["La main droite", "La main gauche", "Les deux pieds"], "bonne": 0, "explication": "On prend l''eau avec la main droite.", "emoji": "👉", "arabe": null}, {"question": "Comment laves-tu ta bouche ?", "choix": ["Je la rince comme pour le brossage, puis je crache", "J''avale toute l''eau", "Je mets du savon"], "bonne": 0, "explication": "On rince la bouche comme pour le brossage des dents, puis on crache.", "emoji": "👄", "arabe": null}, {"question": "Combien de fois laves-tu ta bouche ?", "choix": ["3 fois", "1 fois", "5 fois"], "bonne": 0, "explication": "3 fois, comme pour les mains.", "emoji": "3️⃣", "arabe": null}, {"question": "Quelle main ne met-on pas dans le seau d''eau ?", "choix": ["La main gauche", "La main droite", "On met les deux"], "bonne": 0, "explication": "La fiche le rappelle : on ne met pas la main gauche dans le seau.", "emoji": "🪣", "arabe": null}]'::jsonb,'brouillon','sujet');
