insert into quiz_videos (cible,questions,statut,source) values ('zone:8f8c3788-f505-4bae-a756-00e681546700','[{"question": "Où mets-tu un peu d''eau à cette étape ?", "choix": ["À l''intérieur du nez", "Dans les oreilles", "Sur les pieds"], "bonne": 0, "explication": "On met un peu d''eau à l''intérieur du nez.", "emoji": "👃", "arabe": null}, {"question": "Avec quelle main fais-tu sortir l''eau du nez, comme quand on se mouche ?", "choix": ["La main gauche", "La main droite", "Sans les mains"], "bonne": 0, "explication": "Avec la main gauche, on fait comme si on se mouchait.", "emoji": "🤧", "arabe": null}, {"question": "Combien de fois laves-tu ton nez ?", "choix": ["3 fois", "1 fois", "2 fois"], "bonne": 0, "explication": "3 fois, comme pour les mains et la bouche.", "emoji": "3️⃣", "arabe": null}, {"question": "Quelle étape vient juste AVANT le nez ?", "choix": ["Laver la bouche", "Laver les pieds", "Laver le visage"], "bonne": 0, "explication": "Après la bouche, on lave le nez, puis le visage.", "emoji": "👄", "arabe": null}]'::jsonb,'brouillon','sujet');
