insert into quiz_videos (cible,questions,statut,source) values ('zone:082e516a-00a5-41d9-babf-a293b6259581','[{"question": "Combien de fois laves-tu ton visage ?", "choix": ["3 fois", "1 fois", "4 fois"], "bonne": 0, "explication": "On lave le visage 3 fois.", "emoji": "🙂", "arabe": null}, {"question": "Jusqu''où va le visage, en haut ?", "choix": ["Jusqu''au bord des cheveux", "Jusqu''au milieu du front", "Jusqu''à la nuque"], "bonne": 0, "explication": "Le visage va du bord des cheveux jusqu''en bas du menton.", "emoji": "💇", "arabe": null}, {"question": "Jusqu''où va le visage, en bas ?", "choix": ["En bas du menton", "Au cou", "Au nombril"], "bonne": 0, "explication": "On lave jusqu''en bas du menton.", "emoji": "🧔", "arabe": null}, {"question": "Jusqu''où va le visage, sur les côtés ?", "choix": ["Jusqu''aux oreilles", "Jusqu''aux épaules", "Seulement le nez"], "bonne": 0, "explication": "Sur les côtés, on lave jusqu''à la limite des 2 oreilles.", "emoji": "👂", "arabe": null}, {"question": "Quelle étape vient juste APRÈS le visage ?", "choix": ["Les avant-bras", "Les pieds", "La bouche"], "bonne": 0, "explication": "Après le visage, on lave les avant-bras.", "emoji": "💪", "arabe": null}]'::jsonb,'brouillon','sujet');
