insert into quiz_videos (cible,questions,statut,source) values ('zone:ce6f292b-c167-4a66-9978-3224e626bda7','[{"question": "Combien de fois passes-tu tes mains mouillées sur les cheveux ?", "choix": ["1 seule fois", "3 fois", "5 fois"], "bonne": 0, "explication": "Pour les cheveux, c''est 1 seule fois (et pas 3 fois comme les autres parties).", "emoji": "1️⃣", "arabe": null}, {"question": "Jusqu''où vont tes mains sur les cheveux ?", "choix": ["Jusqu''à la nuque, puis elles reviennent vers le visage", "Seulement sur le front", "Jusqu''au dos"], "bonne": 0, "explication": "Les mains vont jusqu''à la nuque, puis reviennent vers le visage.", "emoji": "💆", "arabe": null}, {"question": "Avec quel doigt fais-tu l''extérieur des oreilles ?", "choix": ["Le pouce", "Le petit doigt", "Aucun doigt"], "bonne": 0, "explication": "Les doigts font l''intérieur des oreilles, le pouce fait l''extérieur.", "emoji": "👍", "arabe": null}, {"question": "Est-ce qu''on verse beaucoup d''eau sur la tête ?", "choix": ["Non, on passe juste les mains mouillées", "Oui, un seau entier", "Oui, on met la tête sous le robinet"], "bonne": 0, "explication": "On passe juste les mains mouillées sur les cheveux.", "emoji": "💧", "arabe": null}]'::jsonb,'brouillon','sujet');
