insert into quiz_videos (cible,questions,statut,source) values ('zone:0eb969f1-cefd-4f83-81fb-856908ba2303','[{"question": "Quel pied laves-tu en premier ?", "choix": ["Le pied droit", "Le pied gauche", "Les deux ensemble"], "bonne": 0, "explication": "On commence par le pied DROIT, puis le gauche.", "emoji": "🦶", "arabe": null}, {"question": "Combien de fois laves-tu chaque pied ?", "choix": ["3 fois", "1 fois", "2 fois"], "bonne": 0, "explication": "3 fois le pied droit, puis 3 fois le pied gauche.", "emoji": "3️⃣", "arabe": null}, {"question": "Jusqu''où laves-tu le pied ?", "choix": ["De la cheville jusqu''aux orteils", "Seulement les orteils", "Jusqu''au genou"], "bonne": 0, "explication": "Du haut de la cheville jusqu''aux orteils.", "emoji": "🦵", "arabe": null}, {"question": "Quelle partie du pied ne faut-il pas oublier ?", "choix": ["Le talon", "Le genou", "La cuisse"], "bonne": 0, "explication": "On n''oublie pas le talon !", "emoji": "👣", "arabe": null}, {"question": "Que peux-tu passer entre les orteils pour bien nettoyer ?", "choix": ["Les doigts de la main gauche", "Un crayon", "Rien du tout"], "bonne": 0, "explication": "Tu peux passer les doigts de la main gauche entre les orteils.", "emoji": "✋", "arabe": null}]'::jsonb,'brouillon','sujet');
