insert into quiz_videos (cible,questions,statut,source) values ('zone:3d68a1f9-2bb8-4606-a571-42c826a8700d','[{"question": "Tu as oublié une partie à laver et tu t''en rends compte vite : que fais-tu ?", "choix": ["Je lave la partie oubliée", "Je fais comme si de rien n''était", "Je pleure"], "bonne": 0, "explication": "Tu refais la partie que tu as oubliée.", "emoji": "🔁", "arabe": null}, {"question": "Et après avoir lavé la partie oubliée ?", "choix": ["Je peux refaire les étapes qui viennent après", "Je dois aller dormir", "Je recommence le lendemain"], "bonne": 0, "explication": "Ensuite, tu peux refaire les étapes qui suivent.", "emoji": "➡️", "arabe": null}, {"question": "Oublier une partie, ça peut arriver à tout le monde ?", "choix": ["Oui, on la refait simplement", "Non, jamais", "Oui, et on ne prie plus"], "bonne": 0, "explication": "Ça arrive : on la refait, et on continue.", "emoji": "😊", "arabe": null}]'::jsonb,'brouillon','sujet');
