insert into quiz_videos (cible,questions,statut,source) values ('zone:97f7e820-e0bb-4119-add5-97a952bd09ec','[{"question": "Quand dis-tu cette invocation ?", "choix": ["À la fin des ablutions", "Au tout début", "En mangeant"], "bonne": 0, "explication": "On la dit quand on a fini les ablutions.", "emoji": "🏁", "arabe": null}, {"question": "Comment commence cette invocation ?", "choix": ["Ach-hadou allâ ilâha illa Allah…", "Bismillah…", "Allahou akbar…"], "bonne": 0, "explication": "« Ach-hadou allâ ilâha illa Allah, wahdahou lâ charîka lah… »", "emoji": "☝️", "arabe": "أَشْهَدُ أَنْ لَا إِلَٰهَ إِلَّا اللَّه"}, {"question": "Que veut dire « lâ ilâha illa Allah » ?", "choix": ["Il n''y a pas de divinité à part Allah", "Allah est le plus grand", "Merci Allah"], "bonne": 0, "explication": "C''est le témoignage : il n''y a pas de divinité à part Allah.", "emoji": "🤲", "arabe": null}, {"question": "Que se passe-t-il pour celui qui dit cette invocation après ses ablutions ?", "choix": ["Les 8 portes du Paradis s''ouvrent pour lui", "Il gagne un jouet", "Rien"], "bonne": 0, "explication": "Le Prophète ﷺ a dit que les 8 portes du Paradis s''ouvrent pour lui, et il entre par celle qu''il veut (Mouslim).", "emoji": "🚪", "arabe": null}, {"question": "Combien de portes a le Paradis, d''après ce hadith ?", "choix": ["8", "3", "100"], "bonne": 0, "explication": "Huit portes, et il entre par celle qu''il désire.", "emoji": "8️⃣", "arabe": null}]'::jsonb,'brouillon','sujet');
